// Host helper: edit an unpublished ext4 partition using the same driver as the OS.
// Invocation: ext4-image-tool VOLUME MANIFEST
// Manifest lines: mkdir PATH | put PATH HOST_FILE | seed PATH HOST_FILE
// Generated by ext4_volume.py, using controlled paths without spaces.
#define _FILE_OFFSET_BITS 64
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/stat.h>
#include <ext4.h>
#include <ext4_blockdev.h>
static FILE *image;
static int io_open(struct ext4_blockdev *bd) { (void)bd; return EOK; }
static int io_read(struct ext4_blockdev *bd, void *buf, uint64_t lba, uint32_t n) {
    if (!n || lba >= bd->bdif->ph_bcnt || n > bd->bdif->ph_bcnt - lba) return EIO;
    return fseeko(image, lba * 512, SEEK_SET) || fread(buf, 512, n, image) != n ? EIO : EOK;
}
static int io_write(struct ext4_blockdev *bd, const void *buf, uint64_t lba, uint32_t n) {
    if (!n || lba >= bd->bdif->ph_bcnt || n > bd->bdif->ph_bcnt - lba) return EIO;
    if (fseeko(image, lba * 512, SEEK_SET) || fwrite(buf, 512, n, image) != n || fflush(image)) return EIO;
    return fsync(fileno(image)) ? EIO : EOK;
}
static int io_close(struct ext4_blockdev *bd) { (void)bd; return fflush(image) || fsync(fileno(image)) ? EIO : EOK; }
static int put(const char *path, const char *source, int seed) {
    uint32_t mode;
    int exists = ext4_mode_get(path, &mode);
    if (exists == EOK && (mode & 0170000) != 0100000) return EINVAL;
    if (seed && exists == EOK) return EOK;
    if (exists != EOK && exists != ENOENT) return exists;
    FILE *in = fopen(source, "rb"); if (!in) return EIO;
    ext4_file f = {0}; int rc = ext4_fopen(&f, path, "wb");
    if (rc) { fclose(in); return rc; }
    unsigned char buf[65536]; size_t n;
    while ((n = fread(buf, 1, sizeof(buf), in))) {
        size_t wrote = 0; rc = ext4_fwrite(&f, buf, n, &wrote);
        if (rc || wrote != n) { if (!rc) rc = EIO; break; }
    }
    if (ferror(in)) rc = EIO;
    fclose(in); int closed = ext4_fclose(&f); return rc ? rc : closed;
}
int main(int argc, char **argv) {
    if (argc != 3) return 2;
    struct stat st;
    if (lstat(argv[1], &st) || !S_ISREG(st.st_mode) || st.st_size % 512) return 2;
    image = fopen(argv[1], "r+b"); if (!image) return 2;
    unsigned char scratch[512];
    struct ext4_blockdev_iface iface = {.open=io_open, .bread=io_read, .bwrite=io_write,
        .close=io_close, .ph_bsize=512, .ph_bcnt=st.st_size/512, .ph_bbuf=scratch};
    struct ext4_blockdev bd = {.bdif=&iface, .part_size=st.st_size};
    int rc = ext4_device_register(&bd, "image");
    if (!rc) rc = ext4_mount("image", "/", false);
    if (!rc) rc = ext4_recover("/");
    if (!rc) rc = ext4_journal_start("/");
    FILE *manifest = rc ? NULL : fopen(argv[2], "r");
    if (!manifest && !rc) rc = EIO;
    char line[2048], op[16], path[512], source[1024];
    while (!rc && fgets(line, sizeof(line), manifest)) {
        int fields = sscanf(line, "%15s %511s %1023s", op, path, source);
        if (fields == 2 && !strcmp(op, "mkdir")) {
            uint32_t mode;
            int exists = ext4_mode_get(path, &mode);
            if (exists == EOK) rc = (mode & 0170000) == 0040000 ? EOK : EINVAL;
            else if (exists == ENOENT) rc = ext4_dir_mk(path);
            else rc = exists;
        } else if (fields == 3 && (!strcmp(op, "put") || !strcmp(op, "seed"))) {
            rc = put(path, source, !strcmp(op, "seed"));
        } else rc = EINVAL;
        if (rc) fprintf(stderr, "ext4 update failed (%d): %s", rc, line);
    }
    if (manifest) { if (ferror(manifest) && !rc) rc = EIO; fclose(manifest); }
    if (!rc) rc = ext4_journal_stop("/");
    if (!rc) rc = ext4_umount("/");
    fclose(image);
    if (rc) fprintf(stderr, "ext4 image helper failed: %d\n", rc);
    return rc ? 1 : 0;
}
